const builders = new Map();                       // name -> () => product

export function register(name, build) {
  if (builders.has(name)) throw new Error(`duplicate: ${name}`);
  builders.set(name, build);
}

export function create(name, ...args) {
  const build = builders.get(name);
  if (!build) throw new Error(`unknown: ${name} (have ${[...builders.keys()].join(', ')})`);
  return build(...args);
}
